class D:
    def __init__(self, v):
        self.v = v
    def go(self, v):
        print('before', v)
        r = v
        print('r=', r)
        print('after', v)
        return r
print(D(0).go(7))

class D:
    def __init__(self, v):
        self.v = v
    def go(self, v):
        r = self.v
        return r
print(D(9).go(1))

class D:
    def __init__(self, v):
        self.v = v
    def go(self, v, w):
        r = w
        return r + v
print(D(0).go(1, 2))
